def choose_move(observation):
    def g(obj, key, default=None):
        try:
            if isinstance(obj, dict):
                return obj.get(key, default)
        except Exception:
            pass
        return default

    def pos(val, default=(0, 0)):
        try:
            if isinstance(val, (list, tuple)) and len(val) >= 2:
                return int(val[0]), int(val[1])
        except Exception:
            pass
        return default

    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [sign(bx - ax), sign(by - ay)]

    def step_away(a, b):
        ax, ay = a
        bx, by = b
        return [sign(ax - bx), sign(ay - by)]

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_target(points, start, mode="min"):
        best = None
        best_score = None
        for p in points or []:
            tp = pos(p, None)
            if tp is None:
                continue
            sc = md(tp, start)
            if best is None or (mode == "min" and sc < best_score) or (mode == "max" and sc > best_score):
                best = tp
                best_score = sc
        return best

    env = g(observation, "environment_name", "resource_collection")
    sx, sy = pos(g(observation, "self_position", (0, 0)))
    ox, oy = pos(g(observation, "opponent_position", (sx, sy)))
    self_p = (sx, sy)
    opp_p = (ox, oy)

    if env == "pursuit_evasion":
        role = g(observation, "self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)
        gw = g(observation, "grid_width", g(observation, "width", 0))
        gh = g(observation, "grid_height", g(observation, "height", 0))
        corners = []
        if gw and gh:
            try:
                corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
            except Exception:
                corners = []
        target = best_target(corners, opp_p, mode="max")
        if target is not None:
            return step_toward(self_p, target)
        return step_away(self_p, opp_p)

    if env == "territory_control":
        targets = g(observation, "unclaimed_cells", None)
        if not targets:
            targets = g(observation, "opponent_territory", None)
        if not targets:
            targets = g(observation, "frontier", None)
        target = best_target(targets, self_p, mode="min")
        if target is not None:
            return step_toward(self_p, target)
        gw = g(observation, "grid_width", g(observation, "width", 0))
        gh = g(observation, "grid_height", g(observation, "height", 0))
        if gw and gh:
            center = (gw // 2, gh // 2)
            return step_toward(self_p, center)
        return step_away(self_p, opp_p)

    resources = g(observation, "resources", None)
    if not resources:
        resources = g(observation, "resource_positions", None)
    target = best_target(resources, self_p, mode="min")
    if target is not None:
        return step_toward(self_p, target)

    return step_away(self_p, opp_p)

